import React, { useState, useEffect } from "react";
import Layout from "../components/Layout";
import API from "../services/api";

function ProfilePage() {
  const [profile, setProfile] = useState({ name: "", email: "", mobileNumber: "" });
  const [loading, setLoading] = useState(true);

  // Profile Update State
  const [editName, setEditName] = useState("");
  const [editMobile, setEditMobile] = useState("");
  const [profileMessage, setProfileMessage] = useState(null);
  const [profileError, setProfileError] = useState(null);
  const [isSavingProfile, setIsSavingProfile] = useState(false);

  // Password Update State
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [passwordMessage, setPasswordMessage] = useState(null);
  const [passwordError, setPasswordError] = useState(null);
  const [isUpdatingPassword, setIsUpdatingPassword] = useState(false);

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      const res = await API.get('/auth/profile');
      setProfile(res.data);
      setEditName(res.data.name || "");
      setEditMobile(res.data.mobileNumber || "");
      setLoading(false);
    } catch (err) {
      console.error("Error fetching profile:", err);
      setLoading(false);
    }
  };

  const handleUpdateProfile = async (e) => {
    e.preventDefault();
    setProfileMessage(null);
    setProfileError(null);
    setIsSavingProfile(true);

    try {
      const res = await API.put('/auth/update-profile', {
        name: editName,
        mobileNumber: editMobile
      });
      setProfile(res.data.user);
      setProfileMessage("Profile details updated successfully!");
    } catch (err) {
      setProfileError(err.response?.data?.message || "Failed to update profile details");
    } finally {
      setIsSavingProfile(false);
    }
  };

  const handleUpdatePassword = async (e) => {
    e.preventDefault();
    setPasswordMessage(null);
    setPasswordError(null);

    if (newPassword !== confirmPassword) {
      setPasswordError("New passwords do not match");
      return;
    }

    setIsUpdatingPassword(true);
    try {
      const res = await API.put('/auth/update-password', {
        currentPassword,
        newPassword
      });
      setPasswordMessage(res.data.message || "Password updated successfully");
      setCurrentPassword("");
      setNewPassword("");
      setConfirmPassword("");
    } catch (err) {
      setPasswordError(err.response?.data?.message || "Failed to update password");
    } finally {
      setIsUpdatingPassword(false);
    }
  };

  if (loading) {
    return (
      <Layout>
        <div className="flex justify-center items-center h-screen bg-background">
            <span className="material-symbols-outlined animate-spin text-4xl text-primary">sync</span>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <main className="relative pt-20 bg-surface min-h-screen">
        <div className="flex flex-col w-full max-w-5xl mx-auto p-6 space-y-8">

          <header className="mb-4">
            <h1 className="font-display-lg text-display-lg text-on-surface">
              Account Profile
            </h1>
            <p className="font-body-md text-on-surface-variant opacity-80 mt-1">
              Manage your personal metadata and security configurations
            </p>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-12 gap-8">

            {/* User Profile Form */}
            <div className="md:col-span-6 flex flex-col gap-6">
              <div className="bg-surface-container/60 backdrop-blur-xl border border-glass-stroke rounded-3xl p-8 shadow-xl flex flex-col h-full">

                <div className="flex items-center gap-4 mb-8">
                  <div className="w-16 h-16 rounded-2xl bg-electric-blue/20 text-electric-blue border border-electric-blue/30 flex items-center justify-center text-2xl font-bold">
                    {profile?.name ? profile.name.charAt(0).toUpperCase() : 'U'}
                  </div>
                  <div>
                    <h2 className="text-xl font-title-lg text-on-surface">{profile?.name || 'Unknown User'}</h2>
                    <span className="px-2 py-0.5 mt-1 inline-block bg-primary/10 text-primary border border-primary/20 rounded font-data-mono text-xs">
                      ADMINISTRATOR
                    </span>
                  </div>
                </div>

                <h3 className="font-headline-md text-on-surface mb-6 flex items-center gap-2">
                  <span className="material-symbols-outlined text-electric-blue">manage_accounts</span>
                  Profile Information
                </h3>

                {profileMessage && (
                  <div className="mb-6 p-4 rounded-xl bg-primary/10 border border-primary/30 text-primary flex items-center gap-3 text-sm">
                    <span className="material-symbols-outlined">check_circle</span>
                    {profileMessage}
                  </div>
                )}

                {profileError && (
                  <div className="mb-6 p-4 rounded-xl bg-error-red/10 border border-error-red/30 text-error-red flex items-center gap-3 text-sm">
                    <span className="material-symbols-outlined">error</span>
                    {profileError}
                  </div>
                )}

                <form onSubmit={handleUpdateProfile} className="flex-1 flex flex-col gap-5 justify-between">
                  <div className="space-y-5">
                    <div>
                      <label className="block text-xs font-label-caps text-on-surface-variant mb-2 tracking-widest">EMAIL ADDRESS (READ-ONLY)</label>
                      <div className="font-body-md text-on-surface-variant bg-surface-dim/50 px-4 py-3.5 rounded-xl border border-glass-stroke">
                        {profile?.email || 'N/A'}
                      </div>
                    </div>
                    <div>
                      <label className="block text-xs font-label-caps text-on-surface-variant mb-2 tracking-widest font-semibold">NAME</label>
                      <input 
                        type="text" 
                        required 
                        value={editName} 
                        onChange={(e) => setEditName(e.target.value)} 
                        className="w-full bg-surface-container-highest border border-glass-stroke rounded-xl p-3.5 text-on-surface focus:border-electric-blue focus:ring-1 focus:ring-electric-blue outline-none transition-all" 
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-label-caps text-on-surface-variant mb-2 tracking-widest font-semibold">MOBILE NUMBER</label>
                      <input 
                        type="text" 
                        required 
                        value={editMobile} 
                        onChange={(e) => setEditMobile(e.target.value)} 
                        className="w-full bg-surface-container-highest border border-glass-stroke rounded-xl p-3.5 text-on-surface focus:border-electric-blue focus:ring-1 focus:ring-electric-blue outline-none transition-all" 
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-label-caps text-on-surface-variant mb-2 tracking-widest">MEMBER SINCE</label>
                      <div className="font-data-mono text-on-surface-variant bg-surface-dim/50 px-4 py-3.5 rounded-xl border border-glass-stroke">
                        {profile?.createdAt ? new Date(profile.createdAt).toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' }) : 'N/A'}
                      </div>
                    </div>
                  </div>

                  <div className="mt-8 border-t border-glass-stroke pt-6 flex justify-end">
                    <button 
                      type="submit" 
                      disabled={isSavingProfile}
                      className="px-8 py-3.5 rounded-full bg-electric-blue text-background font-label-caps tracking-widest hover:bg-opacity-90 transition-all shadow-[0_0_20px_rgba(0,209,255,0.4)] disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                    >
                      {isSavingProfile ? (
                        <>
                          <span className="material-symbols-outlined animate-spin text-[18px]">sync</span>
                          SAVING...
                        </>
                      ) : (
                        <>
                          SAVE CHANGES
                        </>
                      )}
                    </button>
                  </div>
                </form>
              </div>
            </div>

            {/* Password Update Section */}
            <div className="md:col-span-6">
              <div className="bg-surface-container/40 backdrop-blur-xl border border-glass-stroke rounded-3xl p-8 shadow-lg flex flex-col h-full">

                <h3 className="font-headline-md text-on-surface mb-6 flex items-center gap-2">
                  <span className="material-symbols-outlined text-vibrant-violet">lock</span>
                  Security Settings
                </h3>

                {passwordMessage && (
                  <div className="mb-6 p-4 rounded-xl bg-primary/10 border border-primary/30 text-primary flex items-center gap-3 text-sm">
                    <span className="material-symbols-outlined">check_circle</span>
                    {passwordMessage}
                  </div>
                )}

                {passwordError && (
                  <div className="mb-6 p-4 rounded-xl bg-error-red/10 border border-error-red/30 text-error-red flex items-center gap-3 text-sm">
                    <span className="material-symbols-outlined">error</span>
                    {passwordError}
                  </div>
                )}

                <form onSubmit={handleUpdatePassword} className="flex-1 flex flex-col gap-5 justify-between">
                  <div className="space-y-5">
                    <div>
                      <label className="block text-xs font-label-caps text-on-surface-variant mb-2 tracking-widest">CURRENT PASSWORD</label>
                      <input 
                        type="password" 
                        required 
                        value={currentPassword} 
                        onChange={(e) => setCurrentPassword(e.target.value)} 
                        className="w-full bg-surface-container-highest border border-glass-stroke rounded-xl p-3.5 text-on-surface focus:border-vibrant-violet focus:ring-1 focus:ring-vibrant-violet outline-none transition-all" 
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-label-caps text-on-surface-variant mb-2 tracking-widest">NEW PASSWORD</label>
                      <input 
                        type="password" 
                        required 
                        value={newPassword} 
                        onChange={(e) => setNewPassword(e.target.value)} 
                        className="w-full bg-surface-container-highest border border-glass-stroke rounded-xl p-3.5 text-on-surface focus:border-vibrant-violet focus:ring-1 focus:ring-vibrant-violet outline-none transition-all" 
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-label-caps text-on-surface-variant mb-2 tracking-widest">CONFIRM NEW PASSWORD</label>
                      <input 
                        type="password" 
                        required 
                        value={confirmPassword} 
                        onChange={(e) => setConfirmPassword(e.target.value)} 
                        className="w-full bg-surface-container-highest border border-glass-stroke rounded-xl p-3.5 text-on-surface focus:border-vibrant-violet focus:ring-1 focus:ring-vibrant-violet outline-none transition-all" 
                      />
                    </div>
                  </div>

                  <div className="mt-8 border-t border-glass-stroke pt-6 flex justify-end">
                    <button 
                      type="submit" 
                      disabled={isUpdatingPassword}
                      className="px-8 py-3.5 rounded-full bg-vibrant-violet text-background font-label-caps tracking-widest hover:bg-opacity-90 transition-all shadow-[0_0_20px_rgba(139,92,246,0.4)] disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                    >
                      {isUpdatingPassword ? (
                        <>
                          <span className="material-symbols-outlined animate-spin text-[18px]">sync</span>
                          UPDATING...
                        </>
                      ) : (
                        <>
                          UPDATE PASSWORD
                        </>
                      )}
                    </button>
                  </div>
                </form>
              </div>
            </div>

          </div>
        </div>
      </main>
    </Layout>
  );
}

export default ProfilePage;
